KIT_VERSION = "2"

__all__ = ["KIT_VERSION", "BuildCtx"]


class BuildCtx:
    """Per-run Fusion handles + helper methods. Create once at the top
    of run(): ctx = BuildCtx(adsk.core.Application.get())"""

    def __init__(self, app):
        self.app = app
        self.des = adsk.fusion.Design.cast(app.activeProduct)
        self.root = self.des.rootComponent
        self.up = self.des.userParameters
        self.extrudes = self.root.features.extrudeFeatures
        self.patterns = self.root.features.rectangularPatternFeatures
        self.planes = self.root.constructionPlanes
        self.ops = adsk.fusion.FeatureOperations
        self.dims_or = adsk.fusion.DimensionOrientations
        self.dirs = adsk.fusion.ExtentDirections
        self.pt = adsk.core.Point3D.create
        self.cbs = adsk.core.ValueInput.createByString
        self.x_axis = self.root.xConstructionAxis
        self.y_axis = self.root.yConstructionAxis
        self.U = (1.0, 0.0, 0.0)
        self.V = (0.0, 1.0, 0.0)
        self._resolved = {}
        self._circle_jitter = 0

    def val(self, name):
        return self.up.itemByName(name).value  # cm

    def plane_at_z(self, off_expr, name):
        pin = self.planes.createInput()
        pin.setByOffset(self.root.xYConstructionPlane, self.cbs(off_expr))
        pl = self.planes.add(pin)
        pl.name = name
        return pl

    def all_profiles(self, sk):
        coll = adsk.core.ObjectCollection.create()
        for pr in sk.profiles:  # fusionhelper: allow R11 — collection add, not a document mutation
            coll.add(pr)
        return coll

    def bound_rect2(self, sk, w, hu, hv, u_size=None, v_size=None,
                    u_pos=None, v_pos=None):
        """Constrained rectangle. w = world centre; position expressions
        are (centre_expr, half_size_expr) pairs — base is the CENTRE
        coordinate expression (measured: corner-based baselines snapped
        the board to the wrong quadrant)."""
        pt, U, V = self.pt, self.U, self.V
        dims_or = self.dims_or
        c = sk.modelToSketchSpace(pt(w[0], w[1], w[2]))
        pu = sk.modelToSketchSpace(pt(w[0] + U[0], w[1] + U[1], w[2] + U[2]))
        pv = sk.modelToSketchSpace(pt(w[0] + V[0], w[1] + V[1], w[2] + V[2]))
        if abs(pu.x - c.x) >= abs(pu.y - c.y):
            shx, shy = hu, hv
            ax = (u_size, u_pos, 1 if pu.x > c.x else -1)
            ay = (v_size, v_pos, 1 if pv.y > c.y else -1)
        else:
            shx, shy = hv, hu
            ax = (v_size, v_pos, 1 if pv.x > c.x else -1)
            ay = (u_size, u_pos, 1 if pu.y > c.y else -1)
        lines = sk.sketchCurves.sketchLines.addTwoPointRectangle(
            pt(c.x - shx, c.y - shy, 0), pt(c.x + shx, c.y + shy, 0))
        gc = sk.geometricConstraints
        h_line = None
        v_line = None
        for k in range(lines.count):
            ln = lines.item(k)
            s, e = ln.startSketchPoint.geometry, ln.endSketchPoint.geometry
            if abs(e.x - s.x) >= abs(e.y - s.y):
                gc.addHorizontal(ln)
                if h_line is None:
                    h_line = ln
            else:
                gc.addVertical(ln)
                if v_line is None:
                    v_line = ln
        if h_line is None or v_line is None:
            raise RuntimeError("rect missing axis-aligned line")
        corner = lines.item(0).startSketchPoint
        anchor = pt(c.x + shx + 0.5, c.y - shy - 0.5, 0)
        d = sk.sketchDimensions.addDistanceDimension(
            h_line.startSketchPoint, h_line.endSketchPoint,
            dims_or.HorizontalDimensionOrientation, anchor)
        d.parameter.expression = ax[0] if ax[0] else "%.4f mm" % (shx * 20)
        d = sk.sketchDimensions.addDistanceDimension(
            v_line.startSketchPoint, v_line.endSketchPoint,
            dims_or.VerticalDimensionOrientation, anchor)
        d.parameter.expression = ay[0] if ay[0] else "%.4f mm" % (shy * 20)
        for orient, half_sz, (_, pos, sign), cval in (
                (dims_or.HorizontalDimensionOrientation, shx, ax, c.x),
                (dims_or.VerticalDimensionOrientation, shy, ay, c.y)):
            d = sk.sketchDimensions.addDistanceDimension(
                sk.originPoint, corner, orient, anchor)
            if pos is None:
                d.parameter.expression = "%.4f mm" % (abs(cval - half_sz) * 10)
            else:
                # abs() is load-bearing: a distance dimension is unsigned,
                # so a corner expression that evaluates NEGATIVE (any rect
                # centred on the sketch origin, e.g. '0 mm - (9.65 mm)')
                # is stored negative but SNAPPED POSITIVE by the solver,
                # sliding the whole rectangle sideways by its full width.
                # Measured 2026-08-02; abs() confirmed valid in a Fusion
                # expression and keeps the dimension parametric.
                d.parameter.expression = "abs( %s %s (%s) )" % (
                    pos[0], "-" if sign > 0 else "+", pos[1])

    def bound_circle(self, sk, w, r_cm, dia_expr, x_pos=None, v_pos=None):
        """Jittered creation: coincident-coordinate circles trigger silent
        alignment inference then over-constrain (measured). Dims snap it."""
        pt, U = self.pt, self.U
        dims_or = self.dims_or
        c = sk.modelToSketchSpace(pt(w[0], w[1], w[2]))
        pu = sk.modelToSketchSpace(pt(w[0] + U[0], w[1] + U[1], w[2] + U[2]))
        self._circle_jitter += 1
        j = self._circle_jitter
        circle = sk.sketchCurves.sketchCircles.addByCenterRadius(
            pt(c.x + 0.011 + 0.003 * j, c.y + 0.017 + 0.005 * j, 0), r_cm)
        anchor = pt(c.x + r_cm + 0.4, c.y - 0.4, 0)
        if abs(pu.x - c.x) >= abs(pu.y - c.y):
            h_pos, v_pos_ = x_pos, v_pos
        else:
            h_pos, v_pos_ = v_pos, x_pos
        d = sk.sketchDimensions.addDistanceDimension(
            sk.originPoint, circle.centerSketchPoint,
            dims_or.HorizontalDimensionOrientation, anchor)
        d.parameter.expression = (h_pos if h_pos
                                  else "%.4f mm" % (abs(c.x) * 10))
        d = sk.sketchDimensions.addDistanceDimension(
            sk.originPoint, circle.centerSketchPoint,
            dims_or.VerticalDimensionOrientation, anchor)
        d.parameter.expression = (v_pos_ if v_pos_
                                  else "%.4f mm" % (abs(c.y) * 10))
        d = sk.sketchDimensions.addDiameterDimension(circle, anchor)
        d.parameter.expression = dia_expr
        return circle

    # ---- cuts and joins (volume-threshold validation by default) --------

    def _one_side(self, inp, dist_expr, direction):
        ext = adsk.fusion.DistanceExtentDefinition.create(self.cbs(dist_expr))
        inp.setOneSideExtent(ext, direction)

    def _try_dirs(self, kind):
        if kind in self._resolved:
            return (self._resolved[kind], None)
        return (self.dirs.PositiveExtentDirection,
                self.dirs.NegativeExtentDirection)

    def faces_of(self, bodies):
        return sum(b.faces.count for b in bodies)

    def through_cut(self, profs, depth_expr, participants, *,
                    min_vol_cm3=0.02):
        """Symmetric through-cut. Volume-validated (S14/S15: face counts
        can stay flat or DROP on seam-spanning cuts)."""
        return self.sym_cut(profs, depth_expr, participants,
                            min_vol_cm3=min_vol_cm3)

    def sym_cut(self, profs, depth_expr, participants, *, min_vol_cm3=0.02):
        v0 = sum(b.volume for b in participants)
        inp = self.extrudes.createInput(profs, self.ops.CutFeatureOperation)
        inp.setSymmetricExtent(self.cbs(depth_expr), True)
        inp.participantBodies = participants
        f = self.extrudes.add(inp)
        if v0 - sum(b.volume for b in participants) <= min_vol_cm3:
            f.deleteMe()
            raise RuntimeError("symmetric cut removed no volume")
        return f

    def blind_cut(self, profs, dist_expr, participants, kind="cut", *,
                  min_vol_cm3=0.02):
        v0 = sum(b.volume for b in participants)
        for d in self._try_dirs(kind):
            adsk.doEvents()
            if d is None:
                break
            inp = self.extrudes.createInput(
                profs, self.ops.CutFeatureOperation)
            self._one_side(inp, dist_expr, d)
            inp.participantBodies = participants
            f = self.extrudes.add(inp)
            if v0 - sum(b.volume for b in participants) > min_vol_cm3:
                self._resolved[kind] = d
                return f
            f.deleteMe()
        raise RuntimeError("blind cut cut nothing (%s)" % kind)

    def checked_join(self, profs, dist_expr, target, predicate, kind):
        for d in self._try_dirs(kind):
            adsk.doEvents()
            if d is None:
                break
            inp = self.extrudes.createInput(
                profs, self.ops.JoinFeatureOperation)
            self._one_side(inp, dist_expr, d)
            inp.participantBodies = [target]
            f = self.extrudes.add(inp)
            if predicate(target):
                self._resolved[kind] = d
                return f
            f.deleteMe()
        raise RuntimeError("join never satisfied predicate (%s)" % kind)

    def checked_newbody(self, profs, dist_expr, predicate, kind):
        for d in self._try_dirs(kind):
            adsk.doEvents()
            if d is None:
                break
            inp = self.extrudes.createInput(
                profs, self.ops.NewBodyFeatureOperation)
            self._one_side(inp, dist_expr, d)
            f = self.extrudes.add(inp)
            body = f.bodies.item(0)
            if predicate(body):
                self._resolved[kind] = d
                return f, body
            f.deleteMe()
        raise RuntimeError("new body never satisfied predicate (%s)" % kind)

    # ---- patterns -------------------------------------------------------

    def _pattern(self, coll, ax, n, d, validate, adjust):
        """Direction/compute retry ladder. NOTE (S15, measured): a seed
        CUT that removes material from more than one body never
        replicates (R-Pattern85 / PATTERN_FEATURES_NO_PASTE, no causal
        error text) — reshape the seed to cut exactly one body."""
        healthy = (
            adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState,
            adsk.fusion.FeatureHealthStates.WarningFeatureHealthState)
        reasons = []
        perp = self.y_axis if ax == self.x_axis else self.x_axis
        popts = adsk.fusion.PatternComputeOptions
        modes = ((popts.AdjustPatternCompute, popts.IdenticalPatternCompute)
                 if adjust else (None,))
        for dd in (d, "-(%s)" % d):
            adsk.doEvents()
            for mode in modes:
                adsk.doEvents()
                inp = self.patterns.createInput(
                    coll, ax, self.cbs(n), self.cbs(dd),
                    adsk.fusion.PatternDistanceType
                    .SpacingPatternDistanceType)
                inp.setDirectionTwo(perp, self.cbs("1"), self.cbs("0 mm"))
                if mode is not None:
                    inp.patternComputeOption = mode  # pyright: ignore[reportAttributeAccessIssue]
                try:
                    f = self.patterns.add(inp)
                except Exception as e:
                    reasons.append("%s/%s add-raise %s"
                                   % (dd, mode, str(e)[:50]))
                    continue
                if f.healthState in healthy and validate(f):
                    return f
                reasons.append("%s/%s hs=%s" % (dd, mode, f.healthState))
                f.deleteMe()
        raise RuntimeError("pattern never validated: " + " | ".join(reasons))

    def pattern_bodies(self, bodies, ax, n, d, predicate):
        """Body pattern (no compute-option: body patterns reject it).
        predicate(feature) -> bool accepts/rejects the whole pattern —
        e.g. a bounds check that every new body landed inside the part."""
        coll = adsk.core.ObjectCollection.create()
        for b in bodies:  # fusionhelper: allow R11 — collection add, not a document mutation
            coll.add(b)
        f = self._pattern(coll, ax, n, d, predicate, adjust=False)
        out = []
        for i in range(f.bodies.count):
            out.append(f.bodies.item(i))
        return out

    def pattern_cut(self, feats, ax, n, d, watch, *,
                    min_vol_cm3=None, min_new_faces=None):
        """Pattern of cut features. Volume threshold is the default
        choice (S14/S15); face-count is opt-in for small isolated holes.
        Exactly one of min_vol_cm3 / min_new_faces must be given."""
        if (min_vol_cm3 is None) == (min_new_faces is None):
            raise ValueError(
                "pass exactly one of min_vol_cm3 / min_new_faces")
        coll = adsk.core.ObjectCollection.create()
        for f in feats:  # fusionhelper: allow R11 — collection add, not a document mutation
            coll.add(f)
        if min_vol_cm3 is not None:
            v0 = sum(b.volume for b in watch)

            def validate(_f):
                return v0 - sum(b.volume for b in watch) >= min_vol_cm3
        else:
            before = self.faces_of(watch)

            def validate(_f):
                return self.faces_of(watch) - before >= min_new_faces  # pyright: ignore[reportOperatorIssue]
        return self._pattern(coll, ax, n, d, validate, adjust=True)
# fh-bundle: kit end

FH_ATTEMPT = 1
FH_OPTS = {"liveness_budget_s": 180}
INTERFERENCE_ALLOWED = []

MM = 0.1  # art constants are written in mm; the API is cm


# ---- pure-python art generators (all coordinates mm) -------------------

def arc_pts(cx, cy, r, a0_deg, a1_deg, n):
    out = []
    for i in range(n + 1):
        a = math.radians(a0_deg + (a1_deg - a0_deg) * i / n)
        out.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return out


def stroke(centre, w):
    """Closed polygon of constant width w around an open centreline."""
    n = len(centre)
    left, right = [], []
    for i in range(n):
        x0, y0 = centre[max(i - 1, 0)]
        x1, y1 = centre[min(i + 1, n - 1)]
        dx, dy = x1 - x0, y1 - y0
        ln = math.hypot(dx, dy)
        nx, ny = -dy / ln, dx / ln
        x, y = centre[i]
        left.append((x + nx * w / 2, y + ny * w / 2))
        right.append((x - nx * w / 2, y - ny * w / 2))
    return left + right[::-1]


def smile(cx, cy, r, w, half_span_deg=55, n=12):
    return stroke(arc_pts(cx, cy, r, 270 - half_span_deg,
                          270 + half_span_deg, n), w)


def mirror(poly, sx, sy):
    return [(x * sx, y * sy) for x, y in poly]


def clip_rect(poly, x0, y0, x1, y1):
    """Sutherland-Hodgman clip of a convex polygon to a rectangle."""
    def clip(pts, inside, cross):
        out = []
        for i in range(len(pts)):
            a, b = pts[i - 1], pts[i]
            ia, ib = inside(a), inside(b)
            if ia and ib:
                out.append(b)
            elif ia and not ib:
                out.append(cross(a, b))
            elif ib:
                out.append(cross(a, b))
                out.append(b)
        return out

    def xcross(xv):
        return lambda a, b: (xv, a[1] + (b[1] - a[1]) * (xv - a[0])
                             / (b[0] - a[0]))

    def ycross(yv):
        return lambda a, b: (a[0] + (b[0] - a[0]) * (yv - a[1])
                             / (b[1] - a[1]), yv)

    pts = list(poly)
    for inside, cross in (
            (lambda p: p[0] >= x0, xcross(x0)),
            (lambda p: p[0] <= x1, xcross(x1)),
            (lambda p: p[1] >= y0, ycross(y0)),
            (lambda p: p[1] <= y1, ycross(y1))):
        if len(pts) < 3:
            return []
        pts = clip(pts, inside, cross)
    clean = []
    for p in pts:
        if not clean or math.hypot(p[0] - clean[-1][0],
                                   p[1] - clean[-1][1]) > 1e-6:
            clean.append(p)
    if len(clean) > 1 and math.hypot(clean[0][0] - clean[-1][0],
                                     clean[0][1] - clean[-1][1]) < 1e-6:
        clean.pop()
    return clean


def poly_area(poly):
    s = 0.0
    for i in range(len(poly)):
        x0, y0 = poly[i - 1]
        x1, y1 = poly[i]
        s += x0 * y1 - x1 * y0
    return abs(s) / 2


# ---- Fusion helpers -----------------------------------------------------

def fixed_sketch(ctx, plane, name, z_cm, polys=(), circles=()):
    """Fixed-art sketch: closed polylines and circles at mm coordinates,
    mapped through the sketch's own transform (R6), then fixed."""
    sk = ctx.root.sketches.add(plane)
    sk.name = name
    sk.isComputeDeferred = True
    lines = sk.sketchCurves.sketchLines
    for poly in polys:
        adsk.doEvents()
        pts = [sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z_cm))
               for x, y in poly]
        first = lines.addByTwoPoints(pts[0], pts[1])
        prev = first
        for k in range(2, len(pts)):
            adsk.doEvents()
            prev = lines.addByTwoPoints(prev.endSketchPoint, pts[k])
        lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
    for (x, y, r) in circles:
        adsk.doEvents()
        sk.sketchCurves.sketchCircles.addByCenterRadius(
            sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z_cm)), r * MM)
    for c in sk.sketchCurves:
        adsk.doEvents()
        if not c.isFixed:
            c.isFixed = True
    for sp in sk.sketchPoints:
        adsk.doEvents()
        if sp.isFullyConstrained or sp.isFixed:
            continue
        sp.isFixed = True
    sk.isComputeDeferred = False
    want = len(polys) + len(circles)
    if sk.profiles.count != want:
        raise RuntimeError("%s: %d profiles, expected %d"
                           % (name, sk.profiles.count, want))
    return sk


def prof_area(profs):
    total = 0.0
    for i in range(profs.count):
        total += profs.item(i).areaProperties().area
    return total


def depth_cm(ctx, expr):
    return ctx.des.unitsManager.evaluateExpression(expr, "cm")


def extrude(ctx, profs, op, dist_expr, name, participants=None, taper=None):
    inp = ctx.extrudes.createInput(profs, op)
    ext = adsk.fusion.DistanceExtentDefinition.create(ctx.cbs(dist_expr))
    if taper is None:
        inp.setOneSideExtent(ext, ctx.dirs.PositiveExtentDirection)
    else:
        inp.setOneSideExtent(ext, ctx.dirs.PositiveExtentDirection,
                             ctx.cbs(taper))
    if participants is not None:
        inp.participantBodies = participants
    f = ctx.extrudes.add(inp)
    f.name = name
    return f


def new_bodies(ctx, profs, dist_expr, name):
    f = extrude(ctx, profs, ctx.ops.NewBodyFeatureOperation, dist_expr,
                name + "_extrude")
    bodies = [f.bodies.item(i) for i in range(f.bodies.count)]
    if not bodies:
        raise RuntimeError("%s made no body" % name)
    if len(bodies) == 1:
        bodies[0].name = name
    else:
        for i, b in enumerate(bodies):
            b.name = "%s_%d" % (name, i + 1)
    return bodies


def cut_up(ctx, profs, dist_expr, targets, name):
    """Cut upward (+normal) from the sketch plane; volume-validated."""
    want = prof_area(profs) * depth_cm(ctx, dist_expr)
    v0 = sum(b.volume for b in targets)
    extrude(ctx, profs, ctx.ops.CutFeatureOperation, dist_expr,
            name + "_cut", participants=targets)
    dv = v0 - sum(b.volume for b in targets)
    if dv < 0.5 * want:
        raise RuntimeError("%s cut removed %.5f of %.5f cm3"
                           % (name, dv, want))


def join_up(ctx, profs, dist_expr, target, name):
    want = prof_area(profs) * depth_cm(ctx, dist_expr)
    v0 = target.volume
    extrude(ctx, profs, ctx.ops.JoinFeatureOperation, dist_expr,
            name + "_join", participants=[target])
    dv = target.volume - v0
    if dv < 0.4 * want:
        raise RuntimeError("%s join added %.5f of %.5f cm3"
                           % (name, dv, want))


def inlay(ctx, sk, target, depth_expr, name):
    """Flush colour inlay: pocket the target, then fill the pocket with
    new bodies from the same profiles."""
    profs = ctx.all_profiles(sk)
    cut_up(ctx, profs, depth_expr, [target], name)
    return new_bodies(ctx, ctx.all_profiles(sk), depth_expr, name)


def plane_at_y(ctx, expr, name, y_cm):
    """XZ-parallel datum at world y = y_cm. The offset sign is measured,
    never assumed (R6)."""
    for e in (expr, "-(%s)" % expr):
        adsk.doEvents()
        pin = ctx.planes.createInput()
        pin.setByOffset(ctx.root.xZConstructionPlane, ctx.cbs(e))
        pl = ctx.planes.add(pin)
        if abs(pl.geometry.origin.y - y_cm) < 1e-4:
            pl.name = name
            return pl
        pl.deleteMe()
    raise RuntimeError("no offset sign puts %s at y=%.3f" % (name, y_cm))


def leg_sockets(ctx, bodies, edge_expr, edge_cm, x_expr, x_cm,
                z_expr, z_cm):
    """Two round rope/leg sockets bored into the bottom (-Y) edge."""
    pl = plane_at_y(ctx, edge_expr, "leg_socket_plane", -edge_cm)
    sk = ctx.root.sketches.add(pl)
    sk.name = "leg_sockets"
    for sx in (1, -1):
        adsk.doEvents()
        ctx.bound_circle(sk, (sx * x_cm, -edge_cm, z_cm), 0.325,
                         "leg_hole_d", x_pos=x_expr, v_pos=z_expr)
    if sk.profiles.count != 2:
        raise RuntimeError("leg socket profiles %d" % sk.profiles.count)
    f = ctx.sym_cut(ctx.all_profiles(sk), "2 * leg_hole_depth", bodies,
                    min_vol_cm3=0.1)
    f.name = "leg_socket_cut"


def feet_and_legs(ctx, foot_x, foot_y, leg_xs, leg_y):
    """Two biscuit feet with piped-cream tops and rope sockets, plus two
    printable octagonal legs. Positions in mm; foot_y / leg_y signed."""
    root = ctx.root
    # discs
    skd = root.sketches.add(root.xYConstructionPlane)
    skd.name = "foot_discs"
    for sx in (1, -1):
        adsk.doEvents()
        ctx.bound_circle(skd, (sx * foot_x * MM, foot_y * MM, 0), 0.9,
                         "18 mm", x_pos="%g mm" % foot_x,
                         v_pos="%g mm" % abs(foot_y))
    discs = new_bodies(ctx, ctx.all_profiles(skd), "foot_disc_h",
                       "foot_disc")
    if len(discs) != 2:
        raise RuntimeError("foot discs %d" % len(discs))
    # piped cream: 8-point star, tapered inward
    plc = ctx.plane_at_z("foot_disc_h", "foot_cream_plane")
    zc = ctx.val("foot_disc_h")
    stars = []
    for sx in (1, -1):
        star = []
        for i in range(16):
            r = 8.2 if i % 2 == 0 else 6.2
            a = math.radians(i * 22.5)
            star.append((sx * foot_x + r * math.cos(a),
                         foot_y + r * math.sin(a)))
        stars.append(star)
    skc = fixed_sketch(ctx, plc, "foot_cream_stars", zc, polys=stars)
    prism = prof_area(ctx.all_profiles(skc)) * ctx.val("foot_cream_h")
    creams = None
    for taper in ("-12 deg", "12 deg"):
        adsk.doEvents()
        f = extrude(ctx, ctx.all_profiles(skc),
                    ctx.ops.NewBodyFeatureOperation, "foot_cream_h",
                    "foot_cream_extrude", taper=taper)
        got = [f.bodies.item(i) for i in range(f.bodies.count)]
        if sum(b.volume for b in got) < 0.95 * prism:
            creams = got
            break
        f.deleteMe()
    if creams is None or len(creams) != 2:
        raise RuntimeError("foot cream taper never narrowed")
    for i, b in enumerate(creams):
        b.name = "foot_cream_%d" % (i + 1)
    # rope socket down through the cream into the disc
    pls = ctx.plane_at_z("foot_disc_h + foot_cream_h", "foot_top_plane")
    zs = zc + ctx.val("foot_cream_h")
    sks = root.sketches.add(pls)
    sks.name = "foot_sockets"
    for sx in (1, -1):
        adsk.doEvents()
        ctx.bound_circle(sks, (sx * foot_x * MM, foot_y * MM, zs), 0.325,
                         "leg_hole_d", x_pos="%g mm" % foot_x,
                         v_pos="%g mm" % abs(foot_y))
    f = ctx.sym_cut(ctx.all_profiles(sks),
                    "2 * (foot_cream_h + foot_disc_h / 2)",
                    discs + creams, min_vol_cm3=0.1)
    f.name = "foot_socket_cut"
    # printable legs: square bar chamfered to an octagon, lying flat
    skl = root.sketches.add(root.xYConstructionPlane)
    skl.name = "printed_legs"
    for lx in leg_xs:
        adsk.doEvents()
        ctx.bound_rect2(skl, (lx * MM, leg_y * MM, 0), 0.28, 2.75,
                        u_size="leg_w", v_size="leg_len",
                        u_pos=("%g mm" % lx, "leg_w / 2"),
                        v_pos=("%g mm" % leg_y, "leg_len / 2"))
    legs = new_bodies(ctx, ctx.all_profiles(skl), "leg_w", "leg")
    if len(legs) != 2:
        raise RuntimeError("legs %d" % len(legs))
    leg_len_cm = ctx.val("leg_len")
    chf = root.features.chamferFeatures
    for n, leg in enumerate(legs):
        adsk.doEvents()
        coll = adsk.core.ObjectCollection.create()
        for e in leg.edges:  # fusionhelper: allow R11 — collection add, not a document mutation
            if abs(e.length - leg_len_cm) < 0.01:
                coll.add(e)
        if coll.count != 4:
            raise RuntimeError("leg long edges %d != 4" % coll.count)
        v0 = leg.volume
        ci = chf.createInput2()
        ci.chamferEdgeSets.addEqualDistanceChamferEdgeSet(
            coll, ctx.cbs("leg_w * 0.29"), True)
        cf = chf.add(ci)
        cf.name = "leg_octagon_chamfer_%d" % (n + 1)
        if v0 - leg.volume < 0.05 * v0:
            raise RuntimeError("leg chamfer removed too little")
    print("FH feet+legs ok")


def common_params(ctx):
    up, cbs = ctx.up, ctx.cbs
    up.add("inlay_d", cbs("0.6 mm"), "mm", "colour inlay depth")
    up.add("leg_hole_d", cbs("6.5 mm"), "mm", "rope / leg socket dia")
    up.add("leg_hole_depth", cbs("12 mm"), "mm", "socket depth from edge")
    up.add("leg_clear", cbs("0.9 mm"), "mm", "printed leg fit clearance")
    up.add("leg_w", cbs("leg_hole_d - leg_clear"), "mm", "printed leg AF")
    up.add("leg_len", cbs("55 mm"), "mm", "printed leg length")
    up.add("foot_disc_h", cbs("6 mm"), "mm", "foot biscuit height")
    up.add("foot_cream_h", cbs("7 mm"), "mm", "foot cream height")


# ============================ pink wafer =================================
# Printed flat, face up. Bodies: wafer (with layer grooves and raised
# lattice), ink_* (eyes, smile), cheek_*, feet, legs.

WF_W, WF_H = 35.0, 75.0
WF_PITCH = 8.0      # lattice line spacing along x, mm
WF_LINE_W = 1.2
WF_PANELS = ((-14.5, 11.0, 14.5, 34.5), (-14.5, -34.5, 14.5, -9.0))


def wf_lattice(sign):
    """Diagonal ridges x + sign*y = c, clipped to both panels."""
    polys = []
    half = WF_LINE_W / 2 * math.sqrt(2)   # half-width measured along x
    for (x0, y0, x1, y1) in WF_PANELS:
        k = -12
        while k <= 12:
            c = k * WF_PITCH + (y0 + y1) / 2 * sign
            big = 200.0
            # strip between x + sign*y = c - half and c + half
            quad = [(c - half - sign * (-big), -big),
                    (c + half - sign * (-big), -big),
                    (c + half - sign * big, big),
                    (c - half - sign * big, big)]
            poly = clip_rect(quad, x0, y0, x1, y1)
            if len(poly) >= 3 and poly_area(poly) > 4.0:
                polys.append(poly)
            k += 1
    return polys


def run(_context: str):
    app = adsk.core.Application.get()
    ctx = BuildCtx(app)
    root = ctx.root
    up, cbs = ctx.up, ctx.cbs

    up.add("wafer_t", cbs("16 mm"), "mm", "wafer thickness")
    up.add("groove_d", cbs("0.8 mm"), "mm", "layer groove depth")
    up.add("groove_h", cbs("1 mm"), "mm", "layer groove height")
    up.add("relief_h", cbs("0.8 mm"), "mm", "lattice ridge height")
    common_params(ctx)
    print("FH params added")

    t_cm = ctx.val("wafer_t")
    inlay_cm = ctx.val("inlay_d")
    gd = ctx.val("groove_d")
    hw, hh = WF_W / 2 * MM, WF_H / 2 * MM

    sk0 = root.sketches.add(root.xYConstructionPlane)
    sk0.name = "wafer_outline"
    ctx.bound_rect2(sk0, (0, 0, 0), hw, hh,
                    u_size="%g mm" % WF_W, v_size="%g mm" % WF_H,
                    u_pos=("0 mm", "%g mm" % (WF_W / 2)),
                    v_pos=("0 mm", "%g mm" % (WF_H / 2)))
    wafer = new_bodies(ctx, ctx.all_profiles(sk0), "wafer_t", "wafer")[0]
    print("FH block %.3f" % wafer.volume)

    # three layer grooves round the perimeter
    for k in (1, 2, 3):
        adsk.doEvents()
        z_expr = "wafer_t * %d / 4 - groove_h / 2" % k
        pl = ctx.plane_at_z(z_expr, "groove_plane_%d" % k)
        zk = depth_cm(ctx, z_expr)
        skg = root.sketches.add(pl)
        skg.name = "groove_ring_%d" % k
        ctx.bound_rect2(skg, (0, 0, zk), hw + 0.3, hh + 0.3,
                        u_size="%g mm" % (WF_W + 6),
                        v_size="%g mm" % (WF_H + 6),
                        u_pos=("0 mm", "%g mm" % (WF_W / 2 + 3)),
                        v_pos=("0 mm", "%g mm" % (WF_H / 2 + 3)))
        in_w = "(%g mm - 2 * groove_d)" % WF_W
        in_h = "(%g mm - 2 * groove_d)" % WF_H
        ctx.bound_rect2(skg, (0, 0, zk), hw - gd, hh - gd,
                        u_size=in_w, v_size=in_h,
                        u_pos=("0 mm", in_w + " / 2"),
                        v_pos=("0 mm", in_h + " / 2"))
        ring = adsk.core.ObjectCollection.create()
        for p in skg.profiles:  # fusionhelper: allow R11 — collection add, not a document mutation
            if p.profileLoops.count == 2:
                ring.add(p)
        if ring.count != 1:
            raise RuntimeError("groove ring profiles %d" % ring.count)
        v0 = wafer.volume
        extrude(ctx, ring, ctx.ops.CutFeatureOperation, "groove_h",
                "groove_cut_%d" % k, participants=[wafer])
        if v0 - wafer.volume < 0.05:
            raise RuntimeError("groove %d removed %.4f"
                               % (k, v0 - wafer.volume))
    print("FH grooves %.3f" % wafer.volume)

    # raised lattice, one sketch per diagonal direction so every ridge
    # is its own profile (crossing strokes in one sketch fill diamonds)
    pl_top = ctx.plane_at_z("wafer_t", "wafer_top_plane")
    for sign, nm in ((1, "lattice_fwd"), (-1, "lattice_back")):
        adsk.doEvents()
        skl = fixed_sketch(ctx, pl_top, nm, t_cm, polys=wf_lattice(sign))
        join_up(ctx, ctx.all_profiles(skl), "relief_h", wafer, nm)
    print("FH lattice %.3f" % wafer.volume)

    # face inlays in the plain band
    pl_face = ctx.plane_at_z("wafer_t - inlay_d", "face_plane")
    zf = t_cm - inlay_cm
    sk_ink = fixed_sketch(
        ctx, pl_face, "face_ink", zf,
        polys=[smile(0, 4.0, 4.6, 1.2)],
        circles=[(6.0, 5.0, 1.1), (-6.0, 5.0, 1.1)])
    inlay(ctx, sk_ink, wafer, "inlay_d", "ink")
    sk_chk = fixed_sketch(ctx, pl_face, "face_cheeks", zf,
                          circles=[(11.5, 1.5, 2.0), (-11.5, 1.5, 2.0)])
    inlay(ctx, sk_chk, wafer, "inlay_d", "cheek")
    print("FH face ok")

    leg_sockets(ctx, [wafer], "%g mm" % (WF_H / 2), hh,
                "8 mm", 0.8, "wafer_t / 2", t_cm / 2)
    feet_and_legs(ctx, 12, -55, (28, 37), 0)
    print("FH BUILD OK: %d bodies" % root.bRepBodies.count)


# fusionhelper: verification stub v1
def _fh_verify_entry():
    import os, json, traceback
    home = os.environ.get('FUSIONHELPER_HOME') or os.path.join(
        os.environ.get('LOCALAPPDATA', ''), 'FusionHelper')

    def _bail(code, msg):
        return 'FH_VERDICT1 ' + json.dumps(
            {'v': 1, 'status': 'error', 'code': code, 'msg': msg, 'home': home},
            separators=(',', ':'))

    try:
        with open(os.path.join(home, 'fh_verify.py'), encoding='utf-8') as f:
            src = f.read()
    except Exception as e:
        return _bail('verify.block_missing', str(e))
    ns: dict = {'__name__': 'fh_verify'}   # annotated: else pyright infers dict[str, str]
    try:
        exec(compile(src, 'fh_verify.py', 'exec'), ns)
        g = globals()
        return ns['fh_verify'](
            clearances=g.get('CLEARANCES'),
            face_specs=g.get('FACE_SPECS'),
            datum_heights_cm=g.get('DATUM_HEIGHTS_CM'),
            digest=g.get('DIGEST'),
            interference_allowed=g.get('INTERFERENCE_ALLOWED'),
            expect_dead=g.get('EXPECT_DEAD'),
            refs=g.get('FH_REFS', {}),
            attempt=g.get('FH_ATTEMPT', 1),
            **g.get('FH_OPTS', {}))
    except Exception:
        return _bail('verify.internal', traceback.format_exc()[-600:])


def _fh_wrap(inner):
    def _wrapped(_context: str):
        inner(_context)                 # NOT wrapped: build exceptions must escape
        print(_fh_verify_entry())
    return _wrapped


run = _fh_wrap(run)
